float hash(vec2 p) {
    return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453123);
}

float noise(vec2 p) {
    vec2 i = floor(p);
    vec2 f = fract(p);
    vec2 u = f * f * (3.0 - 2.0 * f);
    return mix(mix(hash(i + vec2(0.0, 0.0)), hash(i + vec2(1.0, 0.0)), u.x),
               mix(hash(i + vec2(0.0, 1.0)), hash(i + vec2(1.0, 1.0)), u.x),
               u.y);
}

vec3 Line(vec2 uv, float time)
{
    float thickness = 0.02;
    float glowWidth = 0.1;
    float glowIntensity = 2.5;
    float lineY = 0.0;

    float pulse = abs(sin(time * 2.0)) * 0.05 + glowWidth;

    float noiseFactor = 0.02;
    float dynamicNoise = noise(uv * 10.0 + vec2(0.0, time)) * noiseFactor;

    float distToLine = abs(uv.y - lineY + dynamicNoise);

    float core = smoothstep(thickness, 0.0, distToLine);

    float glow = pow(smoothstep(pulse, 0.0, distToLine), glowIntensity);

    vec3 color = vec3(0.2, 0.6, 1.0) * glow + vec3(1.0, 1.0, 1.0) * core;
    return color;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = fragCoord.xy / iResolution.xy - 0.5;
    uv.x *= iResolution.x / iResolution.y;

    vec3 color = Line(uv, iTime) + Line(uv += vec2(0.1, 0.015), iTime + 0.05);

    fragColor = vec4(color, 1.0);
}
